import{_ as t,o as d,c as o,a3 as a}from"./chunks/framework.I6s8z2kk.js";const u=JSON.parse('{"title":"Search","description":"","frontmatter":{},"headers":[],"relativePath":"dev/domain/search.md","filePath":"dev/domain/search.md"}'),c={name:"dev/domain/search.md"};function r(s,e,n,i,h,l){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h1><p>The <strong>Search</strong> module serves the admin panel&#39;s global search. One request looks up centers, clients, reservations, purchases, client packages, client memberships and services, and returns the hits grouped by type.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><p><code>GET admin/search?q=…&amp;limit=…&amp;locale=…</code> (<code>auth:system_user</code>, 60 requests a minute).</p><table tabindex="0"><thead><tr><th>Param</th><th>Rules</th></tr></thead><tbody><tr><td><code>q</code></td><td>Required, 2–100 characters</td></tr><tr><td><code>limit</code></td><td>Hits per group, 1–10, default 5</td></tr><tr><td><code>locale</code></td><td><code>ar</code> or <code>en</code>, the language of translated titles (service names). If it is missing, Accept-Language is used, then <code>ar</code></td></tr></tbody></table><p>The response is <code>data.&lt;group&gt;[]</code>. Each hit has the same shape: <code>id</code>, <code>title</code>, <code>subtitle</code>, <code>code</code>, <code>center_id</code>, <code>kind</code> and <code>meta</code>. Within a group, hits are newest first. The panel needs <code>center_id</code> and <code>kind</code> to build nested detail routes.</p><h2 id="groups" tabindex="-1">Groups <a class="header-anchor" href="#groups" aria-label="Permalink to &quot;Groups&quot;">​</a></h2><p>Each group is a <code>GlobalSearchProvider</code> in <code>modules/Search/src/Providers</code>. They are registered, in response order, as a tagged list in <code>SearchServiceProvider</code>. <code>GlobalSearch</code> returns nothing for inactive users. It also drops a group the user lacks the permission for, removing its key from the response rather than returning it empty.</p><table tabindex="0"><thead><tr><th>Group</th><th>Permission</th><th>Matches</th></tr></thead><tbody><tr><td><code>centers</code></td><td><code>centers.view_any</code></td><td>Name, slug, contact phone or email</td></tr><tr><td><code>clients</code></td><td><code>clients.view_any</code></td><td>Every word of <code>q</code> must be in the first name, last name or phone (<code>Client::scopeSearch</code>)</td></tr><tr><td><code>reservations</code></td><td><code>centers.manage_reservations</code></td><td>The client (as above), or the exact public <code>code</code></td></tr><tr><td><code>purchases</code></td><td><code>purchases.view_any</code></td><td>Client purchases at centers only (as in <code>AdminPurchaseQuery</code>): the buyer, or the exact <code>code</code></td></tr><tr><td><code>client_packages</code></td><td><code>centers.manage_reservations</code></td><td>The client, or the service name (en/ar). Pending packages are excluded; <code>center_id</code> comes from the service</td></tr><tr><td><code>client_memberships</code></td><td><code>centers.manage_reservations</code></td><td>Same as packages</td></tr><tr><td><code>services</code></td><td><code>centers.manage_services</code></td><td>Name (en/ar) or slug. <code>kind</code> is the admin route segment (e.g. <code>training-services</code>), and <code>meta.serviceable_id</code> is the id under it</td></tr></tbody></table><p>When <code>q</code> looks like a public code (6 characters from the <code>HasUniqueCode</code> alphabet, any case), the exact reservation or purchase is listed first. LIKE wildcards in <code>q</code> are escaped.</p>',10)])])}const m=t(c,[["render",r]]);export{u as __pageData,m as default};
